/** The theme of one ground and accent. Throws on an unknown one. */
export function terminalTheme(ground = DEFAULT_GROUND, accent = DEFAULT_ACCENT) {
  if (!Object.prototype.hasOwnProperty.call(byGround, ground)) {
    throw new Error("unknown ground " + ground);
  }
  if (ACCENTS.indexOf(accent) < 0) throw new Error("unknown accent " + accent);
  const flat = Object.assign({}, byGround[ground], byAccent[ground][accent]);
  const pick = (prefix, names) =>
    Object.freeze(Object.fromEntries(names.map((n) => [n, flat[prefix + n]])));
  return Object.freeze({
    ground,
    accent,
    mode: GROUNDS[ground].mode,
    background: flat.background,
    foreground: flat.foreground,
    cursor: flat.cursor,
    cursorText: flat.cursorText,
    selection: flat.selection,
    selectionForeground: flat.selectionForeground,
    ansi: pick("ansi.", ANSI_NAMES),
    roles: pick("role.", ROLES),
  });
}

/** A brand's theme on its default ground for a mode ("dark" or "light"). */
export function brandTheme(brand, mode = "dark") {
  const b = BRANDS[brand];
  if (!b) throw new Error("unknown brand " + brand);
  if (mode !== "dark" && mode !== "light") throw new Error("unknown mode " + mode);
  return terminalTheme(b.defaultGround[mode], b.accent);
}

/* Degrading ---------------------------------------------------------------- */

/** "#rrggbb" as [r, g, b]. */
export function hexToRgb(hex) {
  const m = /^#?([0-9a-f]{6})$/i.exec(hex);
  if (!m) throw new Error("not a #rrggbb colour: " + hex);
  const n = parseInt(m[1], 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

const toHex = (rgb) => "#" + rgb.map((c) => c.toString(16).padStart(2, "0")).join("");

/**
 * xterm's default values for the sixteen ANSI colours. A terminal's own theme
 * replaces them, so they only stand in for the names (nearestAnsi16 never
 * matches against them by distance).
 */
export const XTERM_16 = Object.freeze([
  "#000000", "#cd0000", "#00cd00", "#cdcd00", "#0000ee", "#cd00cd", "#00cdcd", "#e5e5e5",
  "#7f7f7f", "#ff0000", "#00ff00", "#ffff00", "#5c5cff", "#ff00ff", "#00ffff", "#ffffff",
]);

const CUBE = [0, 95, 135, 175, 215, 255];

/** The colour of an xterm-256 index, as "#rrggbb" (0 to 15 are xterm's defaults). */
export function xterm256Hex(index) {
  if (!Number.isInteger(index) || index < 0 || index > 255) throw new Error("not an xterm-256 index: " + index);
  if (index < 16) return XTERM_16[index];
  if (index >= 232) {
    const v = 8 + (index - 232) * 10;
    return toHex([v, v, v]);
  }
  const i = index - 16;
  return toHex([CUBE[Math.floor(i / 36)], CUBE[Math.floor(i / 6) % 6], CUBE[i % 6]]);
}

/**
 * The nearest xterm-256 index to a colour, from the 6x6x6 cube and the grey
 * ramp (16 to 255). 0 to 15 are left out: the terminal's theme repaints them.
 */
export function nearestXterm256(hex) {
  const rgb = hexToRgb(hex);
  const distance = (other) => {
    const o = hexToRgb(other);
    const rm = (rgb[0] + o[0]) / 2;
    const dr = rgb[0] - o[0];
    const dg = rgb[1] - o[1];
    const db = rgb[2] - o[2];
    // The "redmean" weighting: closer to what an eye calls near than plain RGB.
    return (2 + rm / 256) * dr * dr + 4 * dg * dg + (2 + (255 - rm) / 256) * db * db;
  };
  let best = 16;
  let bestDistance = Infinity;
  for (let i = 16; i < 256; i++) {
    const d = distance(xterm256Hex(i));
    if (d < bestDistance) {
      best = i;
      bestDistance = d;
    }
  }
  return best;
}

const luminance = (rgb) => {
  const lin = (c) => {
    const s = c / 255;
    return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4);
  };
  return 0.2126 * lin(rgb[0]) + 0.7152 * lin(rgb[1]) + 0.0722 * lin(rgb[2]);
};

/** WCAG contrast ratio of two "#rrggbb" colours. */
export function contrast(a, b) {
  const la = luminance(hexToRgb(a));
  const lb = luminance(hexToRgb(b));
  return (Math.max(la, lb) + 0.05) / (Math.min(la, lb) + 0.05);
}

/**
 * The nearest of the sixteen ANSI names to a colour, by hue and lightness
 * rather than by distance to xterm's defaults (which no terminal theme
 * keeps): a near-grey takes black, bright black, white or bright white by
 * lightness; any other colour takes the hue band it falls in, bright when
 * it is light. So a light ground's deep red stays "red" and a dark ground's
 * pale red becomes "brightRed", each the half of the set the terminal's own
 * theme keeps readable on its background.
 */
export function nearestAnsi16(hex) {
  const rgb = hexToRgb(hex);
  const max = Math.max(...rgb);
  const min = Math.min(...rgb);
  const l = luminance(rgb);
  if ((max - min) / 255 < 0.2) {
    if (l < 0.05) return "black";
    if (l < 0.4) return "brightBlack";
    if (l < 0.8) return "white";
    return "brightWhite";
  }
  const [r, g, b] = rgb;
  const d = max - min;
  let hue = max === r ? ((g - b) / d) % 6 : max === g ? (b - r) / d + 2 : (r - g) / d + 4;
  hue = (hue * 60 + 360) % 360;
  // Hue bands as the eye names them, not six even sextants: yellow is
  // narrow, green and blue are wide (a lime is green, an amber yellow).
  const bands = [
    [20, "red"],
    [75, "yellow"],
    [165, "green"],
    [200, "cyan"],
    [285, "blue"],
    [345, "magenta"],
    [360, "red"],
  ];
  const name = bands.find(([end]) => hue < end)[1];
  return l > 0.3 ? "bright" + name[0].toUpperCase() + name.slice(1) : name;
}

/* Detecting ---------------------------------------------------------------- */

/**
 * How many colours the terminal takes: "truecolor", "256", "16" or "none".
 * FORCE_COLOR wins when set (0 or false: none; 1, true or empty: 16; 2: 256;
 * 3: truecolor). Then NO_COLOR, when set and not empty, turns colour off
 * (https://no-color.org). Then a stream that is not a terminal, or
 * TERM=dumb, gets none. COLORTERM=truecolor or 24bit, a TERM ending in
 * -direct or -truecolor, Windows Terminal (WT_SESSION) and the terminals
 * known to take 24-bit colour give truecolor; a TERM with 256color gives
 * 256; anything else 16.
 */
export function detectColorDepth(options = {}) {
  const env = options.env ?? globalThis.process?.env ?? {};
  const isTTY = options.isTTY ?? true;
  const force = env.FORCE_COLOR;
  if (force !== undefined) {
    const f = force.toLowerCase();
    if (f === "0" || f === "false") return "none";
    if (f === "2") return "256";
    if (f === "3") return "truecolor";
    return "16";
  }
  if (env.NO_COLOR) return "none";
  if (!isTTY) return "none";
  const term = (env.TERM ?? "").toLowerCase();
  if (term === "dumb") return "none";
  const colorterm = (env.COLORTERM ?? "").toLowerCase();
  if (colorterm === "truecolor" || colorterm === "24bit") return "truecolor";
  if (/-(direct|truecolor)$/.test(term) || env.WT_SESSION) return "truecolor";
  if (["iTerm.app", "WezTerm", "vscode", "ghostty"].includes(env.TERM_PROGRAM ?? "")) return "truecolor";
  if (term.includes("256color") || env.TERM_PROGRAM === "Apple_Terminal") return "256";
  return "16";
}

/**
 * Whether the terminal's background is dark or light, from COLORFGBG
 * ("15;0": foreground 15 on background 0), which rxvt, Konsole, iTerm2 and
 * others set. Undefined when the terminal does not say: then default to
 * dark and let the person choose.
 */
export function detectBackground(env = globalThis.process?.env ?? {}) {
  const parts = (env.COLORFGBG ?? "").split(";");
  const bg = Number(parts[parts.length - 1]);
  if (parts.length < 2 || !Number.isInteger(bg)) return undefined;
  return bg === 7 || bg >= 9 ? "light" : "dark";
}

/** The SGR escape that sets a colour as foreground (or background) at a depth; "" for none. */
export function sgr(hex, depth, layer = "fg") {
  const base = layer === "bg" ? 48 : 38;
  if (depth === "none") return "";
  if (depth === "truecolor") return "\x1b[" + base + ";2;" + hexToRgb(hex).join(";") + "m";
  if (depth === "256") return "\x1b[" + base + ";5;" + nearestXterm256(hex) + "m";
  const index = ANSI_NAMES.indexOf(nearestAnsi16(hex));
  const code = (index < 8 ? 30 : 90) + (index % 8) + (layer === "bg" ? 10 : 0);
  return "\x1b[" + code + "m";
}

/** Resets every SGR attribute. */
export const RESET = "\x1b[0m";

/**
 * A colour as chalk and Ink take it at a depth: "#rrggbb", "ansi256(n)", a
 * name ("redBright", "gray"), or undefined for none (no colour prop).
 */
export function inkColor(hex, depth) {
  if (depth === "none") return undefined;
  if (depth === "truecolor") return hex.toLowerCase();
  if (depth === "256") return "ansi256(" + nearestXterm256(hex) + ")";
  const name = nearestAnsi16(hex);
  if (name === "brightBlack") return "gray";
  return name.startsWith("bright") ? name[6].toLowerCase() + name.slice(7) + "Bright" : name;
}
